import { expect, test } from "@playwright/test"
import { ORGANIZER } from "./support/accounts"
import { openEventList, signIn } from "./support/auth"

test("captures the payment dialog halfway through its opening transition", async ({ page }) => {
  const target = page.viewportSize()!
  await page.setViewportSize({width:1280,height:800})
  await page.emulateMedia({ reducedMotion: "no-preference" })
  await signIn(page, "organizer", ORGANIZER)
  await openEventList(page)
  await page.getByRole("link", { name: /Letní kemp 2027(?! – demo)/ }).click()
  const sections = page.getByRole("navigation", { name: "Event sections" })
  await expect(sections).toBeVisible()
  const switcher = sections.getByRole("button", { name: "Overview", exact: true })
  if (await switcher.isVisible()) {
    await switcher.click()
    await page.getByRole("menuitem", { name: "Applications", exact: true }).click()
    await page.getByRole("button", { name: /^Filters/ }).click()
  } else {
    await sections.getByRole("link", { name: "Applications", exact: true }).click()
  }
  await page.getByRole("combobox", { name: "Payment", exact: true }).click()
  await page.getByRole("option", { name: "Unpaid", exact: true }).click()
  const filters = page.getByRole("dialog", { name: "Filters" })
  if (await filters.isVisible()) {
    await filters.getByRole("button", { name: "Show applications" }).click()
  }
  await page.getByRole("link", { name: "Record payment" }).first().click()
  await page.setViewportSize(target)
  const record = page.getByRole("button", { name: "Record payment for the term" }).first()
  await expect(record).toBeVisible()

  const paused = page.evaluate(() => {
    return new Promise<number>((resolve) => {
      const observer = new MutationObserver(() => {
        const parts = document.querySelectorAll(
          '[data-slot="dialog-content"][data-state="open"], [data-slot="dialog-overlay"][data-state="open"]',
        )
        if (!parts.length) return
        const animations = Array.from(parts).flatMap((part) => part.getAnimations())
        if (!animations.length) return
        observer.disconnect()
        for (const animation of animations) {
          const duration = animation.effect?.getComputedTiming().duration
          if (typeof duration !== "number") continue
          animation.pause()
          animation.currentTime = duration / 2
        }
        resolve(animations.length)
      })
      observer.observe(document.body, { childList: true, subtree: true })
    })
  })
  await record.click()
  expect(await paused).toBeGreaterThan(0)
  await expect(page.getByRole("dialog", { name: "Record payment" })).toBeVisible()
  await page.screenshot({ path: process.env.SHOT_PATH!, fullPage: false })
})

