import { randomUUID } from "node:crypto"
import { expect, test } from "@playwright/test"
import pg from "pg"
import { e2eDatabaseUrl } from "../scripts/database-url.mjs"
import { ORGANIZER, SUMMER_CAMP_LINK } from "./support/accounts"
import { openEventList, signIn } from "./support/auth"

test("capture room assignment actions", async ({ page }) => {
  const db = new pg.Client({ connectionString: e2eDatabaseUrl() })
  const term = randomUUID()
  const alex = randomUUID()
  const robin = randomUUID()
  await db.connect()
  try {
    const { rows } = await db.query<{ id: string; organizationId: string }>(
      'SELECT id, "organizationId" FROM "event" WHERE "publicToken" = $1',
      [SUMMER_CAMP_LINK.split("/").at(-1)],
    )
    const { id: event, organizationId: organization } = rows[0]
    await db.query(
      `INSERT INTO "term" (id, "organizationId", "eventId", number, name, "startsOn", "endsOn", "priceCzk")
       SELECT $1, $2, $3, COALESCE(MAX(number), 0) + 1, 'Demo accommodation', '2029-01-01', '2029-01-07', 1000
       FROM "term" WHERE "eventId" = $3`,
      [term, organization, event],
    )
    await db.query(
      `INSERT INTO "room" (id, "organizationId", "termId", name, capacity, gender)
       VALUES ($1 || '-01', $2, $1, 'Room 101', 4, 'FEMALE'),
              ($1 || '-02', $2, $1, 'Room 102', 4, 'FEMALE')`,
      [term, organization],
    )
    await db.query(
      `INSERT INTO "application" (id, "organizationId", "eventId", "accessToken", "firstName", "lastName", "birthDate", gender, email, "consentAt")
       VALUES ($1, $3, $4, $1, 'Alex', 'Morgan', '2010-01-01', 'FEMALE', $1 || '@example.com', now()),
              ($2, $3, $4, $2, 'Robin', 'Taylor', '2010-01-01', 'FEMALE', $2 || '@example.com', now())`,
      [alex, robin, organization, event],
    )
    await db.query(
      `INSERT INTO "application_term" (id, "organizationId", "applicationId", "termId", status, "priceCzk")
       VALUES ($1, $3, $1, $4, 'CONFIRMED', 1000), ($2, $3, $2, $4, 'CONFIRMED', 1000)`,
      [alex, robin, organization, term],
    )
    await db.query(
      `INSERT INTO "room_assignment" (id, "organizationId", "applicationTermId", "roomId")
       VALUES ($1, $2, $1, $3)`,
      [robin, organization, term + "-01"],
    )

    await signIn(page, "organizer", ORGANIZER)
    await openEventList(page)
    await page.goto("/organizer/events/" + event + "/rooms?termId=" + term)
    await expect(page.getByRole("heading", { name: "Rooms of the selected term" })).toBeVisible()
    await expect(page.getByText("Alex Morgan", {exact:true}).filter({visible:true}).first()).toBeVisible()
    await expect(page.getByText("Robin Taylor", {exact:true}).filter({visible:true}).first()).toBeVisible()
    await page.waitForLoadState("networkidle")
    await page.screenshot({ path: process.env.SHOT_PATH!, fullPage: true })
  } finally {
    try {
      await db.query('DELETE FROM "application" WHERE id IN ($1, $2)', [alex, robin])
      await db.query('DELETE FROM "term" WHERE id = $1', [term])
    } finally {
      await db.end()
    }
  }
})

