import { test, expect } from "@playwright/test"
import { ORGANIZER } from "./support/accounts"
import { openEventList, signIn } from "./support/auth"

test("capture the organizer program", async ({ page }) => {
  const viewport = page.viewportSize()!
  await page.setViewportSize({ width: 1280, height: 800 })
  await signIn(page, "organizer", ORGANIZER)
  await openEventList(page)
  await page.getByRole("link", { name: /Letní kemp 2027(?! – demo)/ }).click()
  await page
    .getByRole("navigation", { name: "Event sections" })
    .getByRole("link", { name: "Program", exact: true })
    .click()

  const calendar = page.getByRole("region", { name: "Program calendar" })
  await expect(calendar).toBeVisible()
  for (const fixture of [
    { name: "Nature workshop", from: "09:00", to: "10:00", place: "Main lodge" },
    { name: "Trail briefing", from: "09:10", to: "09:15", place: "" },
  ]) {
    const detail = calendar.getByRole("button", { name: `Show details of ${fixture.name}` }).filter({visible:true}).first()
    if (!(await detail.isVisible())) {
      await page.getByRole("button", { name: "Add block" }).click()
      const add = page.getByRole("dialog", { name: "Add block" })
      await expect(add.getByRole("combobox", { name: /^Day/ })).toHaveText("Sunday, 04/07/2027")
      await add.getByLabel(/^Block name/).fill(fixture.name)
      await add.getByLabel(/^From/).fill(fixture.from)
      await add.getByLabel(/^To/).fill(fixture.to)
      await add.getByLabel("Place", { exact: true }).fill(fixture.place)
      await add.getByRole("button", { name: "Add block" }).click()
      await expect(add).toBeHidden()
    }
    await expect(detail).toBeVisible()
  }

  await page.setViewportSize(viewport)
  const day = page.getByRole("combobox", { name: "Day", exact: true })
  if (viewport.width === 360 && process.env.SHOT_PHASE === "after") {
    await expect(day).toHaveText("Sunday, 04/07/2027")
  } else {
    await expect(calendar.getByRole("heading", { name: /Sun.*04\/07/ })).toBeVisible()
  }
  await expect(calendar.getByRole("button", { name: /Show details of Trail briefing/ }).filter({visible:true}).first()).toBeVisible()
  await expect(page.getByText("Block saved", { exact: true })).toHaveCount(0)
  await page.waitForLoadState("networkidle")
  await page.evaluate(() => document.fonts.ready)
  await page.screenshot({ path: process.env.SHOT_PATH!, fullPage: true })
})

